export const icon=(name,size='')=>`<svg class="ico ${size}" aria-hidden="true" viewBox="0 0 24 24">${paths[name]||paths.grid}</svg>`;
const a=(action,label,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const heading=(eyebrow,title,desc,buttons='')=>`<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${buttons}</div></div>`;
const empty=(i,title,desc,button='')=>`<div class="empty"><div class="empty-icon">${icon(i,'xl')}</div><h3>${title}</h3><p>${desc}</p>${button}</div>`;
const stat=(name,value,sub,i,type='')=>`<div class="surface stats-card"><div class="stat-top"><span>${name}</span><div class="stat-icon ${type}">${icon(i)}</div></div><strong>${value}</strong><span class="sub">${sub}</span></div>`;
const pill=(text,kind='')=>{const value=String(text??'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&');return `<span class="pill ${['','mint','yellow','red','blue'].includes(kind)?kind:''}">${e(value)}</span>`;};
export const pctBar=(pct,klass='')=>`<div class="progress-track"><div class="progress-fill ${klass}" style="width:${clamp(pct)}%"></div></div>`;
const isPublished=v=>v?.status==='published';
export function publicationItems(projectId){return derivePublicationRows(all('profiles'),all('publications'),projectId);}
export function publicationStats(projectId){const rows=publicationItems(projectId).filter(x=>x.status!=='na'&&x.profile.status!=='archived');const count=rows.filter(x=>x.status==='published').length;return {total:rows.length,done:count,pending:rows.length-count,percent:rows.length?100*count/rows.length:0};}
const getProgress=id=>{const p=get('projects',id);return p?progressByStage(p,all('tasks'),STAGES):{overall:0,stages:[]};};
function projectBadge(status){const kinds={planned:'blue',active:'mint',paused:'yellow',completed:'mint',archived:''};return pill(PROJECT_STATUSES[status]||status||'Planned',kinds[status]);}
function statusOfTask(t){return t.status==='done'?pill('Done','mint'):isOverdue(t.dueAt)?pill('Overdue','red'):t.status==='blocked'?pill('Blocked','yellow'):pill(t.status==='in_progress'?'In Progress':'To Do');}
function projectCard(p){const {overall}=getProgress(p.id),pub=publicationStats(p.id);return `<article class="surface entity-card"><div class="between"><span class="badge-id">SG / ${e(p.language||'EN')}</span>${projectBadge(p.status||'planned')}</div><h3>${e(p.title)}</h3><p>${e(crop(p.description||'এই ডকুমেন্টারির গবেষণা ও প্রোডাকশনের ধাপগুলো ট্র্যাক করুন।',125))}</p><div class="card-meta">${pill(e(p.priority||'normal'))}${p.targetDate?pill('Due '+e(humanDate(p.targetDate))):''}</div><div class="between tiny"><span class="muted">Production</span><strong>${Math.round(overall)}%</strong></div>${pctBar(overall)}<div class="between tiny"><span class="muted">Publishing checklist</span><span>${pub.done}/${pub.total} Done</span></div><div class="entity-foot"><small class="muted">${e(humanDate(p.createdAt))}</small>${a('open-project','Open project '+icon('arrow','sm'),'btn sm primary',`data-id="${e(p.id)}"`)}</div></article>`;}
function ideaCard(i){return `<article class="surface entity-card"><div class="between">${pill(IDEA_STATUSES[i.status]||'Inbox',i.status==='converted'?'mint':i.status==='shelved'?'yellow':'blue')}${pill(e(i.priority||'normal'))}</div><h3>${e(i.title)}</h3><p>${e(crop(i.description||'দ্রুত সংরক্ষিত ধারণা। পরে বিস্তারিত গবেষণা যোগ করুন।',135))}</p><div class="card-meta"><span class="small-muted">${e(humanDate(i.createdAt))}</span>${i.reviewDate?pill('Review '+e(humanDate(i.reviewDate))):''}</div><div class="entity-foot">${a('edit-idea',icon('edit','sm')+' Edit','btn sm',`data-id="${e(i.id)}"`)}${i.status!=='converted'?a('convert-idea',icon('arrow','sm')+' Start documentary','btn sm soft',`data-id="${e(i.id)}"`):pill('Linked to documentary','mint')}</div></article>`;}
function taskRow(t,compact=false){const p=t.projectId?get('projects',t.projectId):null;return `<div class="list-row"><div class="list-icon" style="background:${t.status==='done'?'#1c4a3b':'#20394b'}">${icon(t.status==='done'?'check-circle':'list-check')}</div><div class="row-content"><strong style="${t.status==='done'?'text-decoration:line-through;opacity:.65':''}">${e(t.title)}</strong><small>${p?e(crop(p.title,32))+' · ':''}${t.dueAt?e(humanDate(t.dueAt,true)):'No deadline'} ${t.stage?'· '+e(STAGES.find(s=>s.id===t.stage)?.en||t.stage):''}</small></div><div class="row-end">${!compact?statusOfTask(t):''}${a('toggle-task',icon(t.status==='done'?'refresh':'check','sm'),'btn sm '+(t.status==='done'?'':'soft'),`data-id="${e(t.id)}" title="${t.status==='done'?'Undo':'Complete'}"`)}${!compact?a('edit-task',icon('edit','sm'),'btn sm',`data-id="${e(t.id)}" title="Edit"`):''}</div></div>`;}
const latestFirst=(a,b)=>new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt);
function todaysTasks(){const end=new Date();end.setHours(23,59,59,999);return all('tasks').filter(x=>x.status!=='done'&&x.dueAt&&new Date(x.dueAt).getTime()<=end.getTime()).sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt));}
export function dashboard(){const ps=all('projects'),ts=all('tasks'),ideas=all('ideas'),profiles=all('profiles').filter(x=>x.status!=='archived'),rem=all('reminders').filter(x=>x.status!=='done'),due=todaysTasks();const active=ps.filter(x=>x.status==='active'||x.status==='planned').length;const overdue=ts.filter(x=>x.status!=='done'&&isOverdue(x.dueAt)).length+rem.filter(x=>isOverdue(x.remindAt)).length;const activeProjects=[...ps].filter(p=>p.status!=='archived').sort(latestFirst).slice(0,4);const nextReminders=[...rem].filter(x=>x.remindAt).sort((a,b)=>new Date(a.remindAt)-new Date(b.remindAt)).slice(0,4);
 return `<section class="hero"><div class="hero-text"><p class="eyebrow">YOUR CREATIVE OPERATIONS • COMMAND CENTER</p><h1>প্রতিটি ধারণা সংরক্ষণ।<br><span class="accent">প্রতিটি কাজের অগ্রগতি নজরে।</span></h1><p>SalimGPT-এর ডকুমেন্টারি, প্রকাশনার চেকলিস্ট, শতাধিক প্রোফাইল এবং ব্যক্তিগত দায়িত্ব—একটি নিরাপদ পরিকল্পনা ব্যবস্থায়। এখানে কোনো কনটেন্ট প্রকাশ হয় না।</p><div class="row wrap">${a('new-idea',icon('plus','sm')+' নতুন ডকুমেন্টারি আইডিয়া','btn primary')}${a('new-reminder',icon('bell','sm')+' রিমাইন্ডার','btn')}</div></div><img src="./assets/hero.svg" alt="" class="hero-img" /></section>
 <div class="grid-4">${stat('Documentary Ideas',ideas.length,'আইডিয়া ব্যাংকে সংরক্ষিত','lightbulb')}${stat('Active Documentaries',active,'পরিকল্পিত বা চলমান','film','alt')}${stat('Profile Registry',profiles.length,'সোশ্যাল প্রোফাইল ও ওয়েবসাইট','globe')}${stat('Needs Attention',overdue,'দেরি হওয়া টাস্ক ও রিমাইন্ডার','alert','warn')}</div>
 <div class="two-col-main section-space"><div class="stack"><div class="surface card"><div class="card-head"><h2>Documentary Pipeline</h2><a href="#" data-nav="projects">সব দেখুন →</a></div>${activeProjects.length?activeProjects.map(p=>{const pr=getProgress(p.id),pub=publicationStats(p.id);return `<div class="list-row"><div class="list-icon">${icon('film')}</div><div class="row-content"><strong>${e(p.title)}</strong><small>Production ${Math.round(pr.overall)}% · Publishing ${pub.done}/${pub.total}</small>${pctBar(pr.overall)}</div>${a('open-project',icon('right','sm'),'btn sm',`data-id="${e(p.id)}"`)}</div>`;}).join(''):empty('film','আপনার Documentary Studio প্রস্তুত','নতুন একটি ডকুমেন্টারি তৈরি করুন, অথবা Idea Bank থেকে কোনো ধারণা শুরু করুন।',a('new-project','Create Documentary','btn sm primary'))}</div><div class="surface card"><div class="card-head"><h2>Today & Overdue Tasks</h2><a href="#" data-nav="tasks">Work planner →</a></div>${due.length?due.slice(0,5).map(x=>taskRow(x,true)).join(''):empty('check-circle','কোনো বকেয়া কাজ নেই','নতুন টাস্ক যোগ করলে নির্ধারিত তারিখ অনুযায়ী এখানে দেখা যাবে।',a('new-task','Add Task','btn sm'))}</div></div><div class="stack"><div class="surface card"><div class="card-head"><h2>Quick Capture</h2><span class="pill mint">INSTANT SAVE</span></div><p class="small-muted">হঠাৎ নতুন বিষয় মাথায় এসেছে? এক লাইনে লিখে সংরক্ষণ করুন।</p><form data-form="quick-idea"><div class="field"><label for="quick-title">Documentary idea</label><input id="quick-title" name="title" required maxlength="180" placeholder="যেমন: হারিয়ে যাওয়া কোনো সভ্যতা..." /></div><button class="btn primary" type="submit" style="width:100%;margin-top:12px">${icon('plus','sm')} Save Idea</button></form></div><div class="surface card"><div class="card-head"><h2>Upcoming Reminders</h2><a href="#" data-nav="reminders">সব দেখুন →</a></div>${nextReminders.length?nextReminders.map(r=>`<div class="list-row"><div class="list-icon">${icon('bell')}</div><div class="row-content"><strong>${e(r.title)}</strong><small>${e(humanDate(r.remindAt,true))}</small></div>${a('done-reminder',icon('check','sm'),'btn sm',`data-id="${e(r.id)}"`)}</div>`).join(''):empty('bell','আপনার রিমাইন্ডার এখানে থাকবে','ফোন, সাক্ষাৎ, ভ্রমণ বা অন্যান্য দায়িত্ব ভুলে যাবেন না।',a('new-reminder','Set Reminder','btn sm'))}</div><div class="announcement">${icon('lock','sm')} <span>Read-only monitoring: এই অ্যাপ থেকে কোনো সোশ্যাল মিডিয়া বা ওয়েবসাইটে পোস্ট বা ভিডিও আপলোড করা যাবে না।</span></div></div></div>`;
}
export function ideasPage(ui){const list=all('ideas').filter(i=>!ui.search||`${i.title} ${i.description||''}`.toLowerCase().includes(ui.search.toLowerCase())).filter(x=>ui.filter==='all'||!ui.filter||x.status===ui.filter);return `${heading('CAPTURE → PLAN → CREATE','Documentary Idea Vault','যখনই কোনো ডকুমেন্টারির বিষয় মাথায় আসবে, সঙ্গে সঙ্গে সংরক্ষণ করুন। পরে সেটিকে পূর্ণাঙ্গ প্রকল্পে রূপ দিন।',a('new-idea',icon('plus','sm')+' নতুন আইডিয়া','btn primary'))}<div class="toolbar"><input class="filter-input" data-search placeholder="বিষয়, ধারণা বা নোট খুঁজুন..." value="${e(ui.search||'')}" aria-label="Search ideas"><select data-filter class="filter-select"><option value="all">All ideas</option>${Object.entries(IDEA_STATUSES).map(([k,v])=>`<option value="${k}" ${ui.filter===k?'selected':''}>${v}</option>`).join('')}</select><span class="pill">${list.length} ideas</span></div>${list.length?`<div class="mini-grid">${list.map(ideaCard).join('')}</div>`:`<div class="surface">${empty('lightbulb','আইডিয়া ব্যাংক এখনো খালি','যে কোনো নতুন বিষয় এক লাইনে Save করুন; এখনই বিস্তারিত পরিকল্পনা করার প্রয়োজন নেই।',a('new-idea','+ Capture First Idea','btn primary'))}</div>`}`;}
export function projectsPage(ui){if(ui.projectId&&get('projects',ui.projectId))return projectDetail(ui);const list=all('projects').filter(x=>!ui.search||`${x.title} ${x.description||''}`.toLowerCase().includes(ui.search.toLowerCase())).filter(x=>!ui.filter||ui.filter==='all'||x.status===ui.filter);return `${heading('DOCUMENTARY WORKSPACE','Documentary Studio','প্রতিটি ডকুমেন্টারির গবেষণা, স্ক্রিপ্ট, ভোকাল, ভিজ্যুয়াল, এডিটিং ও প্রকাশনার অগ্রগতি আলাদা করে দেখুন।',a('new-project',icon('plus','sm')+' New Documentary','btn primary'))}<div class="toolbar"><input class="filter-input" data-search placeholder="ডকুমেন্টারি খুঁজুন..." value="${e(ui.search||'')}"><select data-filter class="filter-select"><option value="all">All status</option>${Object.entries(PROJECT_STATUSES).map(([k,v])=>`<option value="${k}" ${ui.filter===k?'selected':''}>${v}</option>`).join('')}</select></div>${list.length?`<div class="mini-grid">${list.map(projectCard).join('')}</div>`:`<div class="surface">${empty('film','প্রথম ডকুমেন্টারি তৈরি করুন','একটি প্রকল্প তৈরি করলেই গবেষণা থেকে এডিটিং পর্যন্ত সাজানো টাস্ক পাবেন।',a('new-project','Create Documentary','btn primary'))}</div>`}`;}
function stagesPanel(p){const pr=getProgress(p.id),taskList=all('tasks').filter(t=>t.projectId===p.id);return `<div class="two-col-main"><section>${pr.stages.map(s=>{const tasks=taskList.filter(t=>t.stage===s.id);return `<div class="surface stage-card"><div class="stage-header"><div class="stage-title"><div class="stage-circle">${icon(s.icon)}</div><div>${e(s.bn)} <small class="muted">/ ${s.en}</small><div class="badge-count">${s.done}/${s.total} tasks completed</div></div></div><div style="min-width:120px;width:25%"><div class="between tiny"><span class="muted">Progress</span><strong>${Math.round(s.progress)}%</strong></div>${pctBar(s.progress)}</div></div><div class="checklist">${tasks.length?tasks.map(t=>`<div class="check-row"><input type="checkbox" aria-label="Mark ${e(t.title)} complete" data-action="toggle-task" data-id="${e(t.id)}" ${t.status==='done'?'checked':''}/><div style="flex:1;min-width:0"><span class="${t.status==='done'?'done-text':''}">${e(t.title)}</span>${t.dueAt?`<small class="muted"> · ${e(humanDate(t.dueAt))}</small>`:''}</div><button type="button" data-action="edit-task" data-id="${e(t.id)}" title="Edit task">${icon('edit','sm')}</button></div>`).join(''):'<p class="small-muted">এই পর্যায়ে কোনো টাস্ক নেই।</p>'}</div><button class="action-link" data-action="new-task" data-project="${e(p.id)}" data-stage="${s.id}">+ Add task</button></div>`;}).join('')}</section><aside class="stack"><div class="surface card"><div class="card-head"><h2>Production Overview</h2></div><div class="between"><strong style="font-size:32px">${Math.round(pr.overall)}%</strong>${projectBadge(p.status)}</div>${pctBar(pr.overall)}<div class="line"></div><div class="between tiny"><span class="muted">Total tasks</span><strong>${taskList.length}</strong></div><div class="between tiny topgap"><span class="muted">Completed</span><strong>${taskList.filter(t=>t.status==='done').length}</strong></div><div class="between tiny topgap"><span class="muted">Target date</span><strong>${e(humanDate(p.targetDate))}</strong></div><div class="line"></div>${a('edit-project',icon('edit','sm')+' Edit Documentary','btn',`data-id="${e(p.id)}"`)}</div><div class="surface card"><div class="card-head"><h2>Next Action</h2></div>${taskList.find(t=>t.status!=='done')?`<strong>${e(taskList.find(t=>t.status!=='done').title)}</strong><p class="small-muted">পরবর্তী অসম্পন্ন কাজটি এখান থেকে শেষ করুন বা তার সময়সূচি পরিবর্তন করুন।</p>`:empty('check','সব কাজ সম্পন্ন','এই ডকুমেন্টারির প্রোডাকশন কাজগুলো সম্পূর্ণ হয়েছে।')}</div></aside></div>`;}
function publicationsPanel(p,ui){const items=publicationItems(p.id),active=items.filter(x=>x.profile.status!=='archived'),done=active.filter(x=>x.status==='published').length,applicable=active.filter(x=>x.status!=='na'),pct=applicable.length?Math.round(done/applicable.length*100):0;return `<div class="announcement">${icon('shield-check')} <span><strong>Manual external publishing tracker.</strong> এখানে Done মানে আপনি অন্যত্র প্রকাশ করেছেন বলে রেকর্ড করেছেন। অ্যাপটি নিজে কোনো পোস্ট/ভিডিও প্রকাশ করে না। মূল Registry-তে নতুন প্রোফাইল যোগ করলে তা এখানে স্বয়ংক্রিয়ভাবে আসবে।</span></div><div class="pub-banner"><div><small>Publishing Coverage — ${active.length} active destinations</small><br><strong>${done} Published / ${applicable.length} Applicable</strong></div><div style="min-width:120px;width:26%;text-align:right"><strong>${pct}%</strong>${pctBar(pct)}</div></div><div class="surface card"><div class="card-head"><h2>Connected destinations</h2>${a('go-profiles',icon('plus','sm')+' Add in Registry','btn sm')}</div>${items.length?`<div class="toolbar"><input class="filter-input" data-pub-search placeholder="প্রোফাইল খুঁজুন..." value="${e(ui.pubSearch||'')}"><span class="pill mint">${done} Done</span>${pill((applicable.length-done)+' Not Published','yellow')}</div><div class="table-scroll"><table class="publication-table"><thead><tr><th>Destination / Account</th><th>Status</th><th>Published date</th><th>Post link</th><th style="text-align:right">Actions</th></tr></thead><tbody>${items.filter(x=>!ui.pubSearch||`${x.profile.label} ${x.profile.platform}`.toLowerCase().includes(String(ui.pubSearch).toLowerCase())).map(({profile,record,status})=>`<tr><td><div class="row"><div class="profile-logo" style="height:35px;width:35px">${e(initials(profile.platform))}</div><div><strong>${e(profile.label)}</strong><small>${e(profile.platform)} ${profile.status==='archived'?'· Archived':''}</small></div></div></td><td>${pill(PUBLICATION_STATUSES[status],status==='published'?'mint':status==='na'?'':'yellow')}</td><td>${record?.publishedAt?e(humanDate(record.publishedAt,true)):'—'}</td><td>${record?.postUrl?`<a href="${href(record.postUrl)}" target="_blank" rel="noopener noreferrer" class="action-link">Open ${icon('external','sm')}</a>`:'—'}</td><td><div class="cell-actions">${a('toggle-publication',status==='published'?icon('refresh','sm')+' Undo':icon('check','sm')+' Done',`btn sm ${status==='published'?'':'soft'}`,`data-project="${e(p.id)}" data-profile="${e(profile.id)}"`)}${a('edit-publication',icon('edit','sm'),'btn sm',`data-project="${e(p.id)}" data-profile="${e(profile.id)}" title="Edit post link, date or mark N/A"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('globe','কোনো প্রোফাইল যুক্ত নেই','মূল Social & Website Registry-তে যতগুলো প্রোফাইল যুক্ত করবেন, সেগুলো স্বয়ংক্রিয়ভাবে এখানে দেখাবে।',a('go-profiles','+ Open Profile Registry','btn primary'))}</div>`;}
function notesPanel(p){return `<div class="grid-2 mobile-one"><div class="surface card"><div class="card-head"><h2>Documentary Brief & Research</h2>${a('edit-project',icon('edit','sm')+' Edit','btn sm',`data-id="${e(p.id)}"`)}</div><p class="small-muted">মূল লক্ষ্য ও বিবরণ</p><p style="white-space:pre-wrap">${e(p.description||'এখনও বিবরণ যুক্ত করা হয়নি।')}</p><div class="line"></div><p class="small-muted">Research Notes / Source links</p><p style="white-space:pre-wrap;word-break:break-word">${e(p.notes||'প্রকল্প সম্পাদনা করে গবেষণা নোট ও উৎস যুক্ত করুন।')}</p></div><div class="surface card"><div class="card-head"><h2>Project Information</h2></div><div class="kpi-list">${[['Language',p.language||'Not set'],['Priority',p.priority||'normal'],['Created',humanDate(p.createdAt)],['Planned start',humanDate(p.startDate)],['Target completion',humanDate(p.targetDate)],['External publications',String(publicationStats(p.id).done)]].map(([k,v])=>`<div class="between"><span class="muted">${k}</span><strong>${e(v)}</strong></div>`).join('')}</div></div></div>`;}
function projectDetail(ui){const p=get('projects',ui.projectId),pr=getProgress(p.id),tab=ui.projectTab||'production',pub=publicationStats(p.id);return `<button class="btn ghost sm" data-action="back-projects">${icon('left','sm')} Back to documentaries</button><div class="detail-head section-space"><div><p class="eyebrow">DOCUMENTARY CONTROL / ${e(p.language||'EN')}</p><h1>${e(p.title)}</h1><div class="row wrap">${projectBadge(p.status)}${pill('Production '+Math.round(pr.overall)+'%','mint')}${pill('Publishing '+pub.done+'/'+pub.total,'blue')}${p.targetDate?pill('Due '+e(humanDate(p.targetDate))):''}</div></div><div class="heading-actions">${a('new-task',icon('plus','sm')+' Add Task','btn',`data-project="${e(p.id)}"`)}${a('edit-project',icon('edit','sm')+' Edit Project','btn primary',`data-id="${e(p.id)}"`)}</div></div><div class="tabs">${[['production','Production Workflow'],['publishing','Publishing Monitor'],['notes','Research & Notes']].map(([k,v])=>`<button class="tab ${tab===k?'active':''}" data-action="project-tab" data-tab="${k}">${v}</button>`).join('')}</div>${tab==='publishing'?publicationsPanel(p,ui):tab==='notes'?notesPanel(p):stagesPanel(p)}`;}
export function profilesPage(ui){let profiles=all('profiles').filter(p=>!ui.search||`${p.label} ${p.platform} ${p.group||''} ${p.url}`.toLowerCase().includes(ui.search.toLowerCase())).filter(p=>!ui.filter||ui.filter==='all'||p.platform===ui.filter).filter(p=>ui.showArchived||p.status!=='archived');const uniquePl=[...new Set(all('profiles').map(x=>x.platform))].sort();return `${heading('CENTRAL PROFILE REGISTRY','Social & Website Watch','এখানে যতগুলো চ্যানেল, পেজ, প্রোফাইল ও ওয়েবসাইট যুক্ত করবেন, সব ডকুমেন্টারির Publishing Checklist-এ সেগুলো স্বয়ংক্রিয়ভাবে দেখা যাবে। কোনো পোস্টিং ক্ষমতা নেই।',a('new-profile',icon('plus','sm')+' Add Profile / Website','btn primary'))}<div class="announcement">${icon('lock')} <span>শুধু লিংক দিয়ে সব প্ল্যাটফর্মের ফলোয়ার বা সর্বশেষ পোস্ট স্বয়ংক্রিয় জানা যায় না। এই সংস্করণে প্রোফাইল লিংক, ম্যানুয়াল পরিসংখ্যান ও Latest Post তথ্য সংরক্ষণ করা যায়। কোনো API, স্ক্র্যাপিং বা প্রকাশনা কার্যক্রম চালানো হয় না।</span></div><div class="toolbar"><input class="filter-input" data-search placeholder="প্রোফাইল বা প্ল্যাটফর্ম খুঁজুন..." value="${e(ui.search||'')}"><select data-filter class="filter-select"><option value="all">All platforms</option>${uniquePl.map(x=>`<option value="${e(x)}" ${ui.filter===x?'selected':''}>${e(x)}</option>`).join('')}</select><label class="row tiny muted"><input type="checkbox" data-archive-toggle ${ui.showArchived?'checked':''}> Archived দেখুন</label><span class="pill mint">${profiles.length} linked</span></div>${profiles.length?`<div class="mini-grid">${profiles.map(p=>`<article class="surface entity-card"><div class="between"><div class="row"><div class="profile-logo">${e(initials(p.platform))}</div><div><strong>${e(p.platform)}</strong><div class="small-muted">${e(p.group||'SalimGPT')}</div></div></div>${p.status==='archived'?pill('Archived','yellow'):pill('Link only')}</div><h3>${e(p.label)}</h3><p>${e(crop(p.url,60))}</p><div class="card-meta">${p.audience?pill('Audience '+e(neatNumber(p.audience))):pill('Audience unavailable')}${p.lastPostAt?pill('Latest '+e(humanDate(p.lastPostAt)),'mint'):pill('Latest not checked')}</div><div class="entity-foot"><a class="btn sm" href="${href(p.url)}" target="_blank" rel="noopener noreferrer">${icon('external','sm')} Open</a><div class="inline-actions">${a('edit-profile',icon('edit','sm')+' Edit','btn sm',`data-id="${e(p.id)}"`)}${a('archive-profile',icon(p.status==='archived'?'refresh':'archive','sm'),'btn sm',`data-id="${e(p.id)}" title="${p.status==='archived'?'Reactivate':'Archive'}"`)}</div></div></article>`).join('')}</div>`:`<div class="surface">${empty('globe','এখনো কোনো প্রোফাইল নেই','YouTube, Facebook, Instagram, Telegram বা যেকোনো ওয়েবসাইটের লিংক যুক্ত করুন।',a('new-profile','+ Add Your First Profile','btn primary'))}</div>`}`;}
export function tasksPage(ui){const tasks=all('tasks').filter(x=>!ui.search||`${x.title} ${x.details||''}`.toLowerCase().includes(ui.search.toLowerCase())).filter(x=>ui.filter==='all'||!ui.filter||ui.filter==='pending'&&x.status!=='done'||ui.filter===x.status).sort((a,b)=>{if(a.status==='done'&&b.status!=='done')return 1;if(b.status==='done'&&a.status!=='done')return -1;return (a.dueAt?new Date(a.dueAt).getTime():Infinity)-(b.dueAt?new Date(b.dueAt).getTime():Infinity)});return `${heading('SCHEDULES & DEADLINES','Work Planner','ডকুমেন্টারি ও ব্যক্তিগত কাজের ডেডলাইন, অগ্রগতি, ক্যালেন্ডার এবং পরবর্তী করণীয়।',a('new-task',icon('plus','sm')+' New Task','btn primary'))}<div class="toolbar"><input class="filter-input" data-search placeholder="কাজ খুঁজুন..." value="${e(ui.search||'')}"><select class="filter-select" data-filter><option value="all">All tasks</option><option value="pending" ${ui.filter==='pending'?'selected':''}>Pending</option><option value="done" ${ui.filter==='done'?'selected':''}>Done</option><option value="blocked" ${ui.filter==='blocked'?'selected':''}>Blocked</option></select></div><div class="two-col-main"><section class="surface card"><div class="card-head"><h2>Task List</h2>${pill(tasks.length+' tasks')}</div>${tasks.length?tasks.map(t=>taskRow(t)).join(''):empty('list-check','এই তালিকায় কোনো কাজ নেই','ডকুমেন্টারি তৈরির সময় টাস্ক স্বয়ংক্রিয়ভাবে যুক্ত হয়। এছাড়াও নিজের টাস্ক যোগ করতে পারবেন।',a('new-task','Add Task','btn primary'))}</section><section class="surface card">${calendarWidget(ui,all('tasks'),all('reminders'))}</section></div>`;}
function calendarWidget(ui,tasks,reminders){const first=ui.calendarMonth?new Date(ui.calendarMonth+'-01T12:00:00'):new Date();const y=first.getFullYear(),m=first.getMonth(),leading=new Date(y,m,1).getDay(),num=daysInMonth(y,m),cells=[];const eventsForDay=d=>[...tasks.filter(t=>t.dueAt&&dateLocal(t.dueAt)===d&&t.status!=='done').map(x=>({...x,kind:'task'})),...reminders.filter(r=>r.remindAt&&dateLocal(r.remindAt)===d&&r.status!=='done').map(x=>({...x,kind:'reminder'}))];for(let i=0;i<leading;i++)cells.push('<div class="cal-day empty-day"></div>');for(let d=1;d<=num;d++){const dt=dateLocal(new Date(y,m,d)),events=eventsForDay(dt);cells.push(`<button class="cal-day ${dateLocal(new Date())===dt?'today':''}" data-action="calendar-day" data-date="${dt}" title="${events.length} scheduled items"><span class="number">${d}</span><div class="dots">${events.slice(0,7).map(x=>`<i class="cal-dot ${x.kind==='reminder'?'yellow':''}"></i>`).join('')}</div><small>${events.length?events.length+' items':''}</small></button>`);}const prev=dateLocal(new Date(y,m-1,1)).slice(0,7),next=dateLocal(new Date(y,m+1,1)).slice(0,7),selected=ui.selectedDay||dateLocal(new Date());const selectedItems=eventsForDay(selected);return `<div class="calendar-head"><h2 style="margin:0;font-size:15px">${e(first.toLocaleDateString('en-US',{month:'long',year:'numeric'}))}</h2><div class="inline-actions">${a('calendar-prev',icon('left','sm'),'btn sm',`data-month="${prev}"`)}${a('calendar-next',icon('right','sm'),'btn sm',`data-month="${next}"`)}</div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="week-label">${x}</div>`).join('')}${cells.join('')}</div><div class="line"></div><div class="between"><strong>${e(humanDate(selected))}</strong><span class="small-muted">${selectedItems.length} events</span></div>${selectedItems.length?selectedItems.map(x=>`<div class="list-row"><div class="row-content"><strong>${e(x.title)}</strong><small>${x.kind==='reminder'?'Reminder':'Task'}</small></div>${icon(x.kind==='reminder'?'bell':'list-check','sm')}</div>`).join(''):'<p class="small-muted">এই দিনের জন্য কোনো কাজ নেই।</p>'}`;}
export function remindersPage(ui){let list=all('reminders').filter(r=>!ui.search||`${r.title} ${r.details||''}`.toLowerCase().includes(ui.search.toLowerCase())).filter(r=>ui.filter==='all'||!ui.filter||ui.filter==='pending'&&r.status!=='done'||ui.filter==='done'&&r.status==='done').sort((a,b)=>(a.status==='done'?1:0)-(b.status==='done'?1:0)||(new Date(a.remindAt)-new Date(b.remindAt)));let due=list.filter(x=>x.status!=='done'&&isOverdue(x.remindAt)).length;return `${heading('NEVER MISS A COMMITMENT','Personal Reminder Center','কারও সঙ্গে দেখা, ফোন, ভ্রমণ, বিল বা ব্যক্তিগত দায়িত্ব—সময়মতো মনে করিয়ে দেবে যখন অ্যাপ খোলা থাকবে।',a('new-reminder',icon('plus','sm')+' Set Reminder','btn primary'))}<div class="grid-3"><div class="surface stats-card"><div class="stat-top">Total Reminders ${icon('bell')}</div><strong>${list.length}</strong><span class="sub">সব ক্যাটাগরি</span></div><div class="surface stats-card"><div class="stat-top">Overdue ${icon('alert')}</div><strong>${due}</strong><span class="sub">পুনঃস্মরণ প্রয়োজন</span></div><div class="surface stats-card"><div class="stat-top">Completed ${icon('check-circle')}</div><strong>${list.filter(x=>x.status==='done').length}</strong><span class="sub">নির্ধারিত কাজ সম্পন্ন</span></div></div><div class="section-space announcement warn">${icon('bell')} <span><strong>Reminder delivery:</strong> অ্যাপ খোলা থাকলে সময় অনুযায়ী ইন-অ্যাপ ও অনুমতি দেওয়া ব্রাউজার নোটিফিকেশন দেখাবে। অ্যাপ সম্পূর্ণ বন্ধ থাকলে নিশ্চিতভাবে নোটিফিকেশন পাঠানোর জন্য আলাদা Push Server প্রয়োজন—এই ZIP-এ সেটি নেই।</span></div><div class="toolbar"><input class="filter-input" data-search placeholder="রিমাইন্ডার খুঁজুন..." value="${e(ui.search||'')}"><select class="filter-select" data-filter><option value="all">All reminders</option><option value="pending" ${ui.filter==='pending'?'selected':''}>Pending</option><option value="done" ${ui.filter==='done'?'selected':''}>Done</option></select>${a('enable-notifications',icon('bell','sm')+' Browser Alerts','btn sm')}</div>${list.length?list.map(r=>`<div class="reminder-card ${r.status==='done'?'done':isOverdue(r.remindAt)?'overdue':''}"><div class="list-icon">${icon('bell')}</div><div class="rem-body"><h3>${e(r.title)}</h3><p>${e(humanDate(r.remindAt,true))} · ${e(r.category||'Personal')} · ${e(r.recurrence||'Once')}${r.details?' · '+e(crop(r.details,65)):''}</p></div><div class="reminder-actions">${r.status!=='done'?a('done-reminder',icon('check','sm')+' Done','btn sm soft',`data-id="${e(r.id)}"`):pill('Completed','mint')}${r.status!=='done'?a('snooze-reminder',icon('clock','sm')+' Snooze','btn sm',`data-id="${e(r.id)}"`):''}${a('export-reminder-calendar',icon('calendar','sm')+' ICS','btn sm',`data-id="${e(r.id)}" title="Export calendar event"`)}${a('edit-reminder',icon('edit','sm'),'btn sm',`data-id="${e(r.id)}"`)}</div></div>`).join(''):`<div class="surface">${empty('bell','রিমাইন্ডার তৈরি করুন','কোনো গুরুত্বপূর্ণ কথা, দায়িত্ব বা সময় ভুলে যাওয়ার আগে এখানে যোগ করুন।',a('new-reminder','+ Add Reminder','btn primary'))}</div>`}`;}
export function goalsPage(ui){let goals=all('goals').filter(g=>!ui.search||`${g.title} ${g.description||''}`.toLowerCase().includes(ui.search.toLowerCase()));return `${heading('MILESTONES & AMBITIONS','Goals & Future Plans','SalimGPT ও ব্যক্তিগত জীবনের দীর্ঘমেয়াদি লক্ষ্য নির্ধারণ করুন, পরিমাণগত অগ্রগতি হিসাব করুন।',a('new-goal',icon('plus','sm')+' Add Goal','btn primary'))}<div class="toolbar"><input class="filter-input" data-search value="${e(ui.search||'')}" placeholder="লক্ষ্য খুঁজুন..."></div>${goals.length?`<div class="mini-grid">${goals.map(g=>{const percent=g.target?100*Number(g.current||0)/Number(g.target):0;return `<article class="surface entity-card"><div class="between"><span class="badge-id">${e(g.category||'SALIMGPT')}</span>${isOverdue(g.targetDate)&&percent<100?pill('Behind schedule','yellow'):pill(percent>=100?'Achieved':'In progress',percent>=100?'mint':'blue')}</div><h3>${e(g.title)}</h3><p>${e(crop(g.description,110))}</p><div class="between"><strong>${neatNumber(g.current||0)} / ${neatNumber(g.target||0)} ${e(g.unit||'')}</strong><span class="small-muted">${Math.round(clamp(percent))}%</span></div>${pctBar(percent)}<div class="entity-foot"><small class="muted">${e(humanDate(g.targetDate))}</small><div class="inline-actions">${a('goal-progress',icon('plus','sm')+' Progress','btn sm soft',`data-id="${e(g.id)}"`)}${a('edit-goal',icon('edit','sm'),'btn sm',`data-id="${e(g.id)}"`)}</div></div></article>`;}).join('')}</div>`:`<div class="surface">${empty('target','কোনো লক্ষ্য যুক্ত হয়নি','নতুন ব্র্যান্ড, ডকুমেন্টারির সংখ্যা বা ব্যক্তিগত অগ্রগতির লক্ষ্য তৈরি করুন।',a('new-goal','Set Your First Goal','btn primary'))}</div>`}`;}
export function reportsPage(){const ps=all('projects'),tasks=all('tasks'),ideas=all('ideas'),profiles=all('profiles').filter(x=>x.status!=='archived');let total=0,done=0;for(const p of ps){const s=publicationStats(p.id);total+=s.total;done+=s.done;}const completedTasks=tasks.filter(x=>x.status==='done').length;const avg=ps.length?ps.reduce((sum,p)=>sum+getProgress(p.id).overall,0)/ps.length:0;const last7=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const date=dateLocal(d);return {date,label:d.toLocaleDateString('en-US',{weekday:'short'}),count:all('activity').filter(x=>dateLocal(x.createdAt)===date).length};});const max=Math.max(1,...last7.map(x=>x.count));return `${heading('REAL DATA, CLEAR DECISIONS','Progress & Insights','এই রিপোর্ট কেবল অ্যাপে সংরক্ষিত কাজ, ডকুমেন্টারি ও ম্যানুয়াল প্রকাশনার তথ্য থেকে গণনা হয়।',a('export-backup',icon('download','sm')+' Export Report Data','btn'))}<div class="grid-4">${stat('Ideas',ideas.length,'মোট পরিকল্পনার বিষয়','lightbulb')}${stat('Avg. Production',Math.round(avg)+'%','ডকুমেন্টারি অগ্রগতি','film','alt')}${stat('Task Completion',tasks.length?Math.round(completedTasks/tasks.length*100)+'%':'0%','সম্পন্ন '+completedTasks+'/'+tasks.length,'check-circle')}${stat('Publishing Coverage',total?Math.round(done/total*100)+'%':'0%','ম্যানুয়াল রেকর্ড: '+done+'/'+total,'globe')}</div><div class="grid-2 section-space mobile-one"><div class="surface card"><div class="card-head"><h2>Last 7 Days: Recorded Actions</h2><small>আপনার কার্যক্রমের ইতিহাস</small></div><div class="report-band">${last7.map(x=>`<div class="report-col"><strong class="tiny muted">${x.count}</strong><div class="bar" style="height:${10+(x.count/max)*110}px"></div><span>${x.label}</span></div>`).join('')}</div></div><div class="surface card"><div class="card-head"><h2>Documentary Stage Completion</h2></div><div class="kpi-list">${STAGES.map(s=>{const related=tasks.filter(t=>t.stage===s.id),count=related.filter(t=>t.status==='done').length,percent=related.length?count/related.length*100:0;return `<div class="kpi-row"><strong>${e(s.en)}</strong><div class="bar-area">${pctBar(percent)}</div><span class="muted">${count}/${related.length}</span></div>`;}).join('')}</div></div></div><div class="surface card section-space"><div class="card-head"><h2>Documentary Publishing Coverage</h2><small>প্রতিটি অ্যাকাউন্ট/পেজ আলাদা গোনা হয়</small></div>${ps.length?ps.map(p=>{const s=publicationStats(p.id);return `<div class="list-row"><div class="row-content"><strong>${e(p.title)}</strong><small>${s.done} Published · ${s.pending} Not Published · ${s.total} applicable destinations</small>${pctBar(s.percent)}</div>${a('open-project',icon('arrow','sm'),'btn sm',`data-id="${e(p.id)}" data-tab="publishing"`)}</div>`;}).join(''):empty('chart','রিপোর্ট তৈরি হওয়ার অপেক্ষায়','প্রকল্প, টাস্ক ও প্রোফাইল যুক্ত করলে এখানকার রিপোর্ট স্বয়ংক্রিয়ভাবে হালনাগাদ হবে।')}</div>`;}
export function publishingPage(ui){
 const projects=all('projects').filter(p=>p.status!=='archived'&&(!ui.search||`${p.title} ${p.language||''}`.toLowerCase().includes(ui.search.toLowerCase()))),profiles=all('profiles').filter(p=>p.status!=='archived');
 const stats=projects.map(p=>({project:p,pub:publicationStats(p.id)}));const completed=stats.filter(x=>x.pub.total&&x.pub.pending===0).length;
 return `${heading('EXTERNAL RELEASES · MONITORING ONLY','Publishing Control Tower','মূল Registry-তে যুক্ত প্রতিটি চ্যানেল, পেজ ও ওয়েবসাইট এখানে ডকুমেন্টারিভিত্তিক গণনা করা হয়। অ্যাপ থেকে কোনো পোস্ট বা ভিডিও আপলোড হয় না।',a('go-profiles',icon('plus','sm')+' Registry Manage','btn primary'))}
 <div class="announcement">${icon('lock')} Done একটি ম্যানুয়াল রেকর্ড; স্বয়ংক্রিয়ভাবে প্ল্যাটফর্মে পোস্ট যাচাই করা হয় না। নতুন Registry Profile সব ডকুমেন্টারিতে অটোমেটিক দৃশ্যমান হবে।</div>
 <div class="grid-3">${stat('Active destinations',profiles.length,'কেন্দ্রীয় রেজিস্ট্রি','globe')}${stat('Documentaries',stats.length,'আর্কাইভ ছাড়া','film')}${stat('Fully recorded',completed,'প্রাসঙ্গিক সব গন্তব্যে Done','check-circle')}</div>
 <div class="surface card section-space"><div class="card-head"><h2>Documentary release coverage</h2>${pill('No publishing actions','mint')}</div><div class="toolbar"><input class="filter-input" data-search placeholder="ডকুমেন্টারি অনুসন্ধান..." value="${e(ui.search||'')}"></div>${stats.length?`<div class="table-scroll"><table class="publication-table"><thead><tr><th>Documentary</th><th>Coverage</th><th>Published</th><th>Not Published</th><th>Open</th></tr></thead><tbody>${stats.map(({project:p,pub})=>`<tr><td><strong>${e(p.title)}</strong><small>${e(p.language||'English')}</small></td><td style="min-width:140px">${Math.round(pub.percent)}%${pctBar(pub.percent)}</td><td>${pill(String(pub.done)+' Done','mint')}</td><td>${pub.pending}</td><td>${a('open-project','Checklist '+icon('arrow','sm'),'btn sm primary',`data-id="${e(p.id)}" data-tab="publishing"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('film','ডকুমেন্টারি পাওয়া যায়নি','প্রথমে Documentary Studio-তে একটি নতুন প্রকল্প খুলুন।',a('new-project','Create Documentary','btn primary'))}</div>`;
}
function calendarPage(ui){const tasks=all('tasks'),reminders=all('reminders'),upcoming=[...tasks.filter(t=>t.status!=='done'&&t.dueAt).map(t=>({title:t.title,date:t.dueAt,type:'Task'})),...reminders.filter(t=>t.status!=='done'&&t.remindAt).map(t=>({title:t.title,date:t.remindAt,type:'Reminder'}))].sort((a,b)=>new Date(a.date)-new Date(b.date)).slice(0,14);
return `${heading('TIME IS A RESOURCE','Master Calendar','ডকুমেন্টারি ডেডলাইন, ব্যক্তিগত রিমাইন্ডার এবং পরবর্তী কাজের দিনভিত্তিক দৃশ্য।',a('new-task',icon('plus','sm')+' New Task','btn primary'))}<div class="two-col-main"><section>${calendarWidget(ui,tasks,reminders)}</section><section class="surface card"><div class="card-head"><h2>Upcoming schedule</h2>${a('new-reminder','Add Reminder','btn sm')}</div>${upcoming.length?upcoming.map(t=>`<div class="list-row"><div class="list-icon">${icon(t.type==='Task'?'list-check':'bell')}</div><div class="row-content"><strong>${e(t.title)}</strong><small>${e(humanDate(t.date,true))} · ${e(t.type)}</small></div></div>`).join(''):empty('calendar','কোনো আসন্ন কাজ নেই','Task অথবা Reminder যুক্ত করুন।')}</section></div>`;}
function resourcesPage(ui){const list=all('resources').filter(x=>!ui.search||`${x.title} ${x.citation||''} ${x.notes||''} ${(x.tags||[]).join(' ')}`.toLowerCase().includes(ui.search.toLowerCase()));const verified=list.filter(x=>x.status==='verified').length;
return `${heading('RESEARCH, EVIDENCE & CITATIONS','Research Library','গবেষণার নোট, প্রমাণ, উৎসের লিংক ও যাচাইয়ের অবস্থা সংরক্ষণ করুন।',a('new-resource',icon('plus','sm')+' Add Source','btn primary'))}<div class="grid-3">${stat('Saved sources',list.length,'গবেষণার মোট উৎস','file-text')}${stat('Verified',verified,'নিজে যাচাই করা','shield-check')}${stat('To review',list.filter(x=>x.status==='to_read').length,'অধ্যয়ন বাকি','clock')}</div><div class="toolbar section-space"><input class="filter-input" data-search value="${e(ui.search||'')}" placeholder="উৎস, ট্যাগ বা নোট খুঁজুন..."></div>${list.length?`<div class="mini-grid">${list.map(x=>`<article class="surface entity-card"><div class="between">${pill(e(x.type))}${pill(e(x.status),'blue')}</div><h3>${e(x.title)}</h3><p>${e(crop(x.notes||x.citation||'Research reference',145))}</p><div class="card-meta">${x.projectId?pill(e(get('projects',x.projectId)?.title||'Documentary')):''}${(x.tags||[]).slice(0,2).map(t=>pill(e(t))).join('')}</div><div class="entity-foot">${x.url?`<a class="btn sm soft" href="${href(x.url)}" target="_blank" rel="noopener noreferrer">Open Source ↗</a>`:'<small class="muted">No URL</small>'}${a('edit-resource',icon('edit','sm')+' Edit','btn sm',`data-id="${e(x.id)}"`)}</div></article>`).join('')}</div>`:`<div class="surface">${empty('file-text','Research Library এখন খালি','প্রথম গবেষণার উৎস ও নোট সংরক্ষণ করুন।',a('new-resource','Add First Source','btn primary'))}</div>`}`;}
function contactsPage(ui){const list=all('contacts').filter(x=>x.status!=='archived').filter(x=>!ui.search||`${x.name} ${x.organization||''} ${x.role||''}`.toLowerCase().includes(ui.search.toLowerCase()));const due=list.filter(x=>x.nextFollowUp&&isOverdue(x.nextFollowUp)).length;
return `${heading('PEOPLE, PROMISES & FOLLOW-UPS','Contacts & Follow-ups','কাউকে ফোন, সাক্ষাৎ বা কোনো অঙ্গীকার—সব যোগাযোগ ও পরবর্তী ফলোআপের তারিখ এখানে রাখুন।',a('new-contact',icon('plus','sm')+' Add Contact','btn primary'))}<div class="grid-3">${stat('Active contacts',list.length,'সংরক্ষিত যোগাযোগ','users')}${stat('Follow-ups due',due,'ফলোআপ সময় পার হয়েছে','alert')}${stat('Upcoming',list.filter(x=>x.nextFollowUp&&!isOverdue(x.nextFollowUp)).length,'আগামী যোগাযোগ','calendar')}</div><div class="toolbar section-space"><input class="filter-input" data-search value="${e(ui.search||'')}" placeholder="ব্যক্তি বা প্রতিষ্ঠান খুঁজুন..."></div>${list.length?`<div class="mini-grid">${list.map(x=>`<article class="surface entity-card"><div class="between"><span class="badge-id">${e(x.organization||'CONTACT')}</span>${x.nextFollowUp&&isOverdue(x.nextFollowUp)?pill('Follow-up due','yellow'):pill(e(x.priority||'normal'))}</div><h3>${e(x.name)}</h3><p>${e(x.role||'Contact')}</p><div class="small-muted">${x.phone?`Phone: ${e(x.phone)}<br>`:''}${x.email?`Email: ${e(x.email)}<br>`:''}Next follow-up: ${e(humanDate(x.nextFollowUp))}</div><div class="entity-foot">${a('new-reminder',icon('bell','sm')+' Reminder','btn sm')}${a('edit-contact',icon('edit','sm')+' Edit','btn sm primary',`data-id="${e(x.id)}"`)}</div></article>`).join('')}</div>`:`<div class="surface">${empty('users','কোনো যোগাযোগ যোগ করা হয়নি','একটি গুরুত্বপূর্ণ ব্যক্তি বা ফলোআপ সংরক্ষণ করুন।',a('new-contact','Add Contact','btn primary'))}</div>`}`;}
function activityPage(){const list=all('activity').slice(0,250),today=dateLocal();const todayItems=list.filter(x=>dateLocal(x.createdAt)===today).length;
return `${heading('TRACE EVERY STEP','Activity Journal','নতুন আইডিয়া, টাস্ক, Publishing Done, রিমাইন্ডার ও অন্যান্য পরিবর্তনের অ্যাপ-রেকর্ড। এটি অপরিবর্তনযোগ্য আইনগত Audit Log নয়।',a('export-backup',icon('download','sm')+' Export Backup','btn primary'))}<div class="grid-3">${stat('Events shown',list.length,'সাম্প্রতিক সর্বোচ্চ ২৫০','clock')}${stat('Today',todayItems,'আজকের নথিভুক্ত কাজ','check-circle')}${stat('History',all('activity').length,'মোট সংরক্ষিত ঘটনা','list-check')}</div><div class="surface card section-space"><div class="card-head"><h2>Recent changes</h2>${pill('Local + GitHub Sync')}</div>${list.length?list.map(x=>`<div class="list-row"><div class="list-icon">${icon('clock')}</div><div class="row-content"><strong>${e(x.action)}</strong><small>${e(crop(x.detail,180))}</small><small>${e(humanDate(x.createdAt,true))}</small></div></div>`).join(''):empty('clock','এখনো কোনো ইতিহাস নেই','অ্যাপে কাজ শুরু করলে এখানে নথি দেখা যাবে।')}</div>`;}
function helpPage(){return `${heading('START WITH CONFIDENCE','User Guide & Boundaries','এই অ্যাপটি কেবল পরিকল্পনা এবং পর্যবেক্ষণের জন্য। GitHub Private Repository-তে সংরক্ষণের সঠিক পদ্ধতি এখানে দেখুন।')}<div class="grid-2 mobile-one"><div class="surface card"><h2>01 · দ্রুত শুরু</h2><p>Idea Vault → New Idea → Documentary Studio-তে Convert → Stage Checklist → Publishing Monitor-এ Done। Registry-তে নতুন প্রোফাইল যোগ করলে তা স্বয়ংক্রিয়ভাবে সব ডকুমেন্টারিতে দৃশ্যমান হয়।</p><h2>02 · GitHub Data Sync</h2><p>Settings থেকে <strong>salimpersonal / SalimGPT-Private-Data</strong> নির্বাচন করুন। শুধু ওই Private Repository-র Contents Read/Write অনুমতিযুক্ত Fine-grained PAT প্রবেশ করুন। Token ব্রাউজারে স্থায়ীভাবে রাখা হয় না; প্রতিটি নতুন সেশনে আবার দিতে হবে।</p><h2>03 · Recovery</h2><p>ব্রাউজারের ডেটা মুছে গেলে Settings-এ GitHub পুনরায় Connect করে Sync Now চাপুন। শুধু GitHub-এ সফলভাবে সেভ হওয়া তথ্যই ফিরে আসবে।</p></div><div class="stack"><div class="surface card"><h2>04 · যা এই অ্যাপ করে না</h2><p>Social media বা ওয়েবসাইটে পোস্ট/ভিডিও প্রকাশ করে না। Social Profile-এর লিংক থেকে স্বয়ংক্রিয় Followers, latest posts বা full analytics সংগ্রহ করে না।</p></div><div class="surface card"><h2>05 · রিমাইন্ডারের সীমা</h2><p>অ্যাপ খোলা থাকা অবস্থায় সময় পরীক্ষা ও অনুমোদিত ব্রাউজার Notification দেওয়া হয়। অ্যাপ বন্ধ থাকলে GitHub Pages একা ব্যাকগ্রাউন্ড Push পাঠাতে পারে না। ICS Calendar export ডিভাইসে Import করা যায়।</p></div><div class="surface card"><h2>06 · নিরাপদ ব্যবহার</h2><p>Public Repository-তে Data বা Token রাখবেন না। Sync সফল না হলে ব্রাউজারের ডেটা Clear করবেন না। সংবেদনশীল ব্যক্তিগত তথ্যের জন্য নিজস্ব ডিভাইস ও GitHub অ্যাকাউন্টে 2FA ব্যবহার করুন।</p></div></div></div>`;}
function settingsPage(){const connected=isSignedIn(),session=getCloudSession(),cfg=getCloudConfig(),activities=all('activity').slice(0,5),pending=pendingCount();
return `${heading('GITHUB ONLY · PRIVATE DATA','Settings & Recovery','দুটি Repository: প্রথমটিতে অ্যাপ, দ্বিতীয়টিতে ব্যক্তিগত ডেটা। Supabase বা Firebase প্রয়োজন নেই।',a('export-backup',icon('download','sm')+' Export Backup','btn primary'))}
<div class="grid-3">${stat('Local records',allRows().length,'IndexedDB-তে রাখা','database')}${stat('Pending GitHub',pending,'GitHub-এ সেভ এখনো বাকি',pending?'alert':'check-circle')}${stat('Sync conflicts',conflicts.length,'সমাধানের অপেক্ষা','shield-check')}</div>
<div class="grid-2 mobile-one section-space"><div class="stack">
<div class="surface card settings-section"><div class="card-head"><h2>Private GitHub Data Repository</h2>${pill(connected?'Connected':'Not Connected',connected?'mint':'yellow')}</div>
<p>Data Store হিসেবে শুধু PRIVATE GitHub Repository সমর্থিত। কোনো token এই অ্যাপের কোড, IndexedDB, LocalStorage বা GitHub Pages-এ লেখা হয় না।</p>
<form data-form="cloud-config"><div class="form-grid"> <div class="field"><label>Repository owner</label><input type="text" name="owner" value="${e(cfg.owner)}" required maxlength="100" pattern="[A-Za-z0-9_.-]+"></div><div class="field"><label>Private repository name</label><input type="text" name="repo" value="${e(cfg.repo)}" required maxlength="100" pattern="[A-Za-z0-9_.-]+"></div></div><button type="submit" class="btn sm topgap">Save Repository Address</button></form>
${connected?`<div class="announcement">${icon('check-circle')} Connected as <strong>${e(session?.user?.login||'GitHub user')}</strong> · ${e(session?.repo?.full_name||'Private Data')}</div><div class="inline-actions">${a('sync-cloud',icon('refresh','sm')+' Sync Now','btn primary',syncing?'disabled':'')}${a('signout-cloud','Disconnect Token','btn')}</div>`:`<form data-form="cloud-auth" class="topgap"><div class="field"><label>Fine-grained PAT — paste for this browser session only</label><input type="password" name="token" required minlength="25" autocomplete="off" spellcheck="false" placeholder="github_pat_..."></div><p class="dialog-note">Required repository permission: <strong>Contents → Read and write</strong> for only SalimGPT-Private-Data. Token is kept in RAM and forgotten when app reloads or closes.</p><button type="submit" class="btn primary topgap">${icon('lock','sm')} Verify & Connect GitHub</button></form>`}
<div class="topgap dialog-note"><strong>Sync status:</strong> ${e(syncing?'Syncing now':syncStatus)} · <strong>Last success:</strong> ${e(humanDate(lastSync,true))}</div>${lastSyncError?`<div class="announcement warn">${icon('alert')} ${e(lastSyncError)}</div>`:''}
<p class="dialog-note">Internet reconnected while app is open? Sync resumes when connected. With no token after browser restart, reconnect manually. Cloud is not guaranteed until Sync status says Saved and Pending = 0.</p>
</div>
${conflicts.length?`<div class="surface card"><h2>Sync conflicts (${conflicts.length})</h2><p>দুটি ডিভাইস একই রেকর্ড বদলেছে। কোন সংস্করণ রাখবেন?</p>${conflicts.map((c,i)=>`<div class="list-row"><div class="row-content"><strong>${e(c.local.data?.title||c.local.data?.label||c.local.data?.name||c.collection)}</strong><small>${e(c.collection)}</small></div>${a('conflict-local','Keep Local','btn sm',`data-index="${i}"`)}${a('conflict-remote','Keep GitHub','btn sm',`data-index="${i}"`)}</div>`).join('')}</div>`:''}
</div><div class="stack"><div class="surface card settings-section"><div class="card-head"><h2>Data Backup & Recovery</h2>${pill('Local-first','mint')}</div><p>Cloud Sync ছাড়াও JSON Backup আলাদা করে সংরক্ষণ করতে পারেন। Browser data Clear করার আগে নিশ্চিত করুন Pending = 0 ও GitHub-এ সফল Sync হয়েছে।</p>
<div class="inline-actions">${a('export-backup','Download JSON Backup','btn')}${a('import-backup','Import JSON Backup','btn')}${a('clear-local','Clear Local Records','btn danger')}</div><input id="import-file" accept="application/json,.json" type="file" hidden><div class="topgap">${a('load-demo','Load labeled Demo Data','btn sm')}</div></div>
<div class="surface card settings-section"><h2>Notification Permission</h2><p>Browser Notification কেবল অ্যাপ খোলা থাকলে নির্ভরযোগ্যভাবে পরীক্ষা হবে; OS Calendar ব্যবহারের জন্য প্রতিটি রিমাইন্ডার ICS ফাইলে Export করা যায়।</p>${a('enable-notifications',icon('bell','sm')+' Enable Notifications','btn')}</div>
<div class="surface card settings-section"><h2>Zero-Publishing Policy</h2><div class="announcement">${icon('shield-check')} No posting, no automatic video uploads, no scraping, no background social publishing. Registry profiles are link-only with manual activity notes.</div></div>
<div class="surface card"><h2>Recent activity</h2>${activities.length?activities.map(x=>`<div class="list-row"><div class="row-content"><strong>${e(x.action)}</strong><small>${e(crop(x.detail,65))} · ${e(humanDate(x.createdAt,true))}</small></div></div>`).join(''):'<p class="small-muted">এখনো কোনো পরিবর্তন নেই।</p>'}</div></div></div>`;
}

export function renderView(ui){switch(ui.page){case 'dashboard':return dashboard();case 'ideas':return ideasPage(ui);case 'projects':return projectsPage(ui);case 'profiles':return profilesPage(ui);case 'tasks':return tasksPage(ui);case 'calendar':return calendarPage(ui);case 'publishing':return publishingPage(ui);case 'contacts':return contactsPage(ui);case 'resources':return resourcesPage(ui);case 'activity':return activityPage();case 'help':return helpPage();case 'reminders':return remindersPage(ui);case 'goals':return goalsPage(ui);case 'reports':return reportsPage();case 'settings':return settingsPage();default:return dashboard();}}
export function layout(ui,content,modalHtml=''){const selected=NAV.find(x=>x.id===ui.page)||NAV[0];return `<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-img" src="./assets/icon.svg" alt="SG"><div><strong>Salim<span>GPT</span></strong><small>COMMAND CENTER</small></div></div><div class="nav-scroll"><p class="nav-section">WORKSPACE</p>${NAV.slice(0,9).map(n=>`<button type="button" data-nav="${n.id}" class="nav-item ${ui.page===n.id?'active':''}">${icon(n.icon)}<span>${n.bn}<span class="nav-en">${n.en}</span></span></button>`).join('')}<p class="nav-section">LIFE & INSIGHTS</p>${NAV.slice(9).map(n=>`<button type="button" data-nav="${n.id}" class="nav-item ${ui.page===n.id?'active':''}">${icon(n.icon)}<span>${n.bn}<span class="nav-en">${n.en}</span></span></button>`).join('')}</div><div class="sidebar-foot"><div class="mode-row"><i class="tiny-dot ${isSignedIn()?'cloud':''}"></i>${isSignedIn()?'GitHub private sync active':'Local records only'}</div><div class="side-note">MONITORING ONLY · কোনো অ্যাকাউন্টে পোস্ট বা আপলোড নয়।</div></div></aside><div class="main"><header class="topbar"><div class="bread"><span class="crumb">Workspace / </span><strong>${e(selected.en)}</strong></div><div class="search-wrap" data-action="open-search">${icon('search','sm')}<input aria-label="Global quick search" placeholder="Quick search..." data-search value="${e(ui.search||'')}" /><kbd>⌘ K</kbd></div><div class="top-actions">${a('new-idea',icon('plus','sm')+' <span class="hide-mobile">Quick Idea</span>','btn sm primary')}${a('sync-cloud',icon('refresh','sm'),'icon-button',`title="Sync Cloud" ${!isSignedIn()?'disabled':''}`)}${a('enable-notifications',icon('bell','sm'),'icon-button',`title="Browser Notifications"`)}<div class="avatar" title="SalimGPT">SG</div></div></header><main class="content" id="main-content">${content}</main></div></div><nav class="mobile-tabs">${['dashboard','ideas','projects','publishing','reminders'].map(id=>{const n=NAV.find(x=>x.id===id);return `<button data-nav="${n.id}" class="${ui.page===id?'active':''}">${icon(n.icon)}<span>${e(n.en.split(' ')[0])}</span></button>`;}).join('')}<button data-action="mobile-more" class="${!['dashboard','ideas','projects','publishing','reminders'].includes(ui.page)?'active':''}">${icon('menu')}<span>More</span></button></nav>${modalHtml}<div id="toast-root" class="toast-root" aria-live="polite"></div>`;}
